   371→  private spawnPoop() {
   372→    if (this.gameOver) return;
   373→
   374→    // 난이도에 따른 개수만큼 생성 (각각 다른 높이에서)
   375→    const poopCount = this.difficultyConfig.poopCount;
   376→    for (let i = 0; i < poopCount; i++) {
   377→      // 💩이 화면 전체에서 생성되도록 (💩 크기 15를 고려해서 양쪽 여유)
   378→      const x = Phaser.Math.Between(15, 385);
   379→      const y = Phaser.Math.Between(-200, -20);
   380→      const poop = new Poop(this, x, y, this.difficultyLevel, this.difficulty);
   381→      this.poops.add(poop, true);
   382→
   383→      // 명시적으로 velocity 설정 (그룹 추가 후)
   384→      if (poop.body) {
   385→        // 난이도 기본 속도 + 시간에 따른 증가
   386→        const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * 40);
   387→        poop.body.velocity.y = fallSpeed;
   388→      }
   389→    }
   390→
   391→  }
   392→
   393→  private spawnStars() {
   394→    if (this.gameOver) return;
   395→
   396→    // 별 6개를 랜덤 위치에 생성
   397→    const starCount = 6;
   398→    for (let i = 0; i < starCount; i++) {
   399→      const x = Phaser.Math.Between(15, 385);
   400→      const y = Phaser.Math.Between(-200, -20);
   401→      const star = new Star(this, x, y);
   402→      this.stars.add(star, true);
   403→
   404→      // 명시적으로 velocity 설정 (그룹 추가 후)
   405→      if (star.body) {
   406→        star.body.velocity.y = 200;
   407→      }
   408→    }
   409→  }
