   426→  private spawnGoldPoop() {
   427→    if (this.gameOver) return;
   428→
   429→    // 금똥 1개를 화면 중앙 상단에서 생성 (더 잘 보이도록)
   430→    const x = Phaser.Math.Between(50, 350);
   431→    const y = -50; // 화면에 더 가깝게 시작
   432→    const goldPoop = new GoldPoop(this, x, y);
   433→    this.goldPoops.add(goldPoop, true);
   434→
   435→    // 일반 똥보다 느린 속도로 설정 (난이도에 따라, 설정 기반)
   436→    if (goldPoop.body) {
   437→      const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.gold.speedReduction;
   438→      goldPoop.body.velocity.y = fallSpeed;
   439→    }
   440→
   441→    // console.log(`금똥 생성! 점수: ${this.score}, 위치: (${x}, ${y}), depth: ${goldPoop.depth}`);
   442→  }
   443→
   444→  private spawnDiamondPoop() {
   445→    // console.log('[다이아똥] spawnDiamondPoop 메서드 호출됨');
   446→    if (this.gameOver) {
   447→      // console.log('[다이아똥] 게임 오버 상태라 생성 안 함');
   448→      return;
   449→    }
   450→
   451→    // 다이아똥 1개를 화면 중앙 상단에서 생성 (더 잘 보이도록)
   452→    const x = Phaser.Math.Between(50, 350);
   453→    const y = -50; // 화면에 더 가깝게 시작
   454→    // console.log(`[다이아똥] DiamondPoop 객체 생성 시도: x=${x}, y=${y}`);
   455→    const diamondPoop = new DiamondPoop(this, x, y);
   456→    // console.log(`[다이아똥] DiamondPoop 객체 생성 완료: visible=${diamondPoop.visible}, alpha=${diamondPoop.alpha}`);
   457→
   458→    this.diamondPoops.add(diamondPoop, true);
