   497→  /**
   498→   * 점수가 증가하는 동안 건너뛴 생성 포인트를 확인하고 생성
   499→   * @param oldScore 이전 점수
   500→   * @param newScore 새 점수
   501→   */
   502→  private checkMissedSpawnPoints(oldScore: number, newScore: number) {
   503→    // 40점 단위로 금똥 생성 체크
   504→    for (let score = oldScore + 1; score <= newScore; score++) {
   505→      // 피버 타임 체크
   506→      this.checkFeverTime(score);
   507→
   508→      // 피버 타임 중이 아닐 때만 일반 금똥/다이아똥 생성
   509→      if (!this.isFeverTime) {
   510→        // 40점마다 금똥 생성 (40, 80, 120, 160, ...)
   511→        if (score % 40 === 0 && score > this.lastGoldPoopScore) {
   512→          this.spawnGoldPoop();
   513→          this.lastGoldPoopScore = score;
   514→        }
   515→
   516→        // 100점마다 다이아똥 생성 (100, 200, 300, ...)
   517→        if (score % 100 === 0 && score > this.lastDiamondPoopScore) {
   518→          this.spawnDiamondPoop();
   519→          this.lastDiamondPoopScore = score;
   520→        }
   521→      }
   522→    }
   523→  }
