   528→      // 생성 주기 단축 (최소 400ms, 초기 spawnDelay 기준으로 감소)
   529→      const newDelay = Math.max(400, this.difficultyConfig.spawnDelay - (this.difficultyLevel * 80));
   530→
   531→      // 기존 타이머 제거하고 새로 생성
   532→      this.spawnTimer.remove();
   533→      this.spawnTimer = this.time.addEvent({
   534→        delay: newDelay,
   535→        callback: this.isFeverTime ? this.spawnFeverPoop : this.spawnPoop,
   536→        callbackScope: this,
   537→        loop: true
   538→      });
   539→    }
   540→  }
