   542→  /**
   543→   * 피버 타임 발동 조건 체크 (설정 기반)
   544→   */
   545→  private checkFeverTime(score: number) {
   546→    if (score < FEVER_TIME_CONFIG.firstTriggerScore) return;
   547→
   548→    // 첫 피버 타임 또는 반복 간격 체크
   549→    let nextFeverScore: number;
   550→    const secondTrigger = FEVER_TIME_CONFIG.firstTriggerScore + FEVER_TIME_CONFIG.repeatInterval;
   551→
   552→    if (score < secondTrigger) {
   553→      nextFeverScore = FEVER_TIME_CONFIG.firstTriggerScore;
   554→    } else {
   555→      const feverIndex = Math.floor((score - FEVER_TIME_CONFIG.firstTriggerScore) / FEVER_TIME_CONFIG.repeatInterval);
   556→      nextFeverScore = FEVER_TIME_CONFIG.firstTriggerScore + feverIndex * FEVER_TIME_CONFIG.repeatInterval;
   557→    }
   558→
   559→    if (score >= nextFeverScore && this.lastFeverTimeScore < nextFeverScore) {
   560→      this.startFeverTime();
   561→      this.lastFeverTimeScore = nextFeverScore;
   562→    }
   563→  }
