   565→  /**
   566→   * 피버 타임 시작 (기존 똥을 보너스 아이템으로 변환)
   567→   */
   568→  private startFeverTime() {
   569→    if (this.gameOver) return;
   570→
   571→    this.isFeverTime = true;
   572→    this.feverTimeRemaining = FEVER_TIME_CONFIG.duration;
   573→
   574→    // 기존 일반 똥들을 금똥/다이아똥으로 변환
   575→    if (this.poops) {
   576→      const poopPositions: Array<{ x: number; y: number; velocity: number }> = [];
   577→
   578→      // 모든 똥의 위치와 속도 저장
   579→      this.poops.children.entries.forEach((poop) => {
   580→        const poopSprite = poop as Poop;
   581→        if (poopSprite.body) {
   582→          poopPositions.push({
   583→            x: poopSprite.x,
   584→            y: poopSprite.y,
   585→            velocity: poopSprite.body.velocity.y
   586→          });
   587→        }
   588→      });
   589→
   590→      // 기존 똥들 제거
   591→      this.poops.clear(true, true);
   592→
   593→      // 같은 위치에 금똥/다이아똥 생성 (50:50 확률)
   594→      poopPositions.forEach((pos) => {
   595→        const isGold = Math.random() < 0.5;
   596→
   597→        if (isGold) {
   598→          const goldPoop = new GoldPoop(this, pos.x, pos.y);
   599→          this.goldPoops.add(goldPoop, true);
   600→          if (goldPoop.body) {
   601→            goldPoop.body.velocity.y = pos.velocity * FEVER_TIME_CONFIG.speedMultiplier;
   602→          }
   603→        } else {
   604→          const diamondPoop = new DiamondPoop(this, pos.x, pos.y);
   605→          this.diamondPoops.add(diamondPoop, true);
   606→          if (diamondPoop.body) {
   607→            diamondPoop.body.velocity.y = pos.velocity * FEVER_TIME_CONFIG.speedMultiplier;
   608→          }
   609→        }
   610→      });
   611→    }
   612→
   613→    // 기존 금똥/다이아똥 속도만 증가
   614→    if (this.goldPoops) {
   615→      this.goldPoops.children.entries.forEach((goldPoop) => {
   616→        const goldPoopSprite = goldPoop as GoldPoop;
   617→        if (goldPoopSprite.body) {
   618→          goldPoopSprite.body.velocity.y *= FEVER_TIME_CONFIG.speedMultiplier;
   619→        }
   620→      });
   621→    }
   622→    if (this.diamondPoops) {
   623→      this.diamondPoops.children.entries.forEach((diamondPoop) => {
   624→        const diamondPoopSprite = diamondPoop as DiamondPoop;
   625→        if (diamondPoopSprite.body) {
   626→          diamondPoopSprite.body.velocity.y *= FEVER_TIME_CONFIG.speedMultiplier;
   627→        }
   628→      });
   629→    }
   630→
   631→    // spawnTimer를 피버 타임 생성 패턴으로 교체
   632→    this.spawnTimer.remove();
   633→    this.spawnTimer = this.time.addEvent({
   634→      delay: this.difficultyConfig.spawnDelay,
   635→      callback: this.spawnFeverPoop,
   636→      callbackScope: this,
   637→      loop: true
   638→    });
   639→
   640→    // UI 텍스트 생성 (각 글자별로 개별 Text 객체 생성)
   641→    // 기존 텍스트 제거
   642→    this.feverTimeUITexts.forEach((text) => text.destroy());
   643→    this.feverTimeUITexts = [];
   644→    this.feverTimeColorOffset = 0;
   645→
   646→    const initialSeconds = Math.ceil(FEVER_TIME_CONFIG.duration / 1000);
   647→    const fullText = `FEVER TIME ${initialSeconds}초`;
   648→
   649→    // 무지개 색상 배열 (빨강, 주황, 노랑, 초록, 파랑, 남색, 보라)
   650→    const rainbowColors = [
   651→      '#ff0000', // 빨강
   652→      '#ff7f00', // 주황
   653→      '#ffff00', // 노랑
   654→      '#00ff00', // 초록
   655→      '#0000ff', // 파랑
   656→      '#4b0082', // 남색
   657→      '#9400d3'  // 보라
   658→    ];
   659→
   660→    // 글자 크기 측정을 위한 임시 텍스트
   661→    const tempText = this.add.text(0, 0, fullText, {
   662→      fontSize: FEVER_TIME_CONFIG.ui.fontSize,
   663→      fontStyle: 'bold'
   664→    });
   665→    const totalWidth = tempText.width;
   666→    tempText.destroy();
   667→
   668→    // 각 글자의 시작 X 위치 계산
   669→    const startX = FEVER_TIME_CONFIG.ui.position.x - totalWidth / 2;
   670→    let currentX = startX;
   671→
   672→    // 각 글자별로 Text 객체 생성
   673→    for (let i = 0; i < fullText.length; i++) {
   674→      const char = fullText[i];
   675→      const colorIndex = i % rainbowColors.length;
   676→
   677→      const charText = this.add.text(
