   717→  /**
   718→   * 피버 타임 카운트다운 업데이트
   719→   */
   720→  private updateFeverTime() {
   721→    this.feverTimeRemaining -= 100; // 0.1초씩 감소
   722→
   723→    const secondsRemaining = Math.ceil(this.feverTimeRemaining / 1000);
   724→    const newText = `FEVER TIME ${secondsRemaining}초`;
   725→
   726→    // 각 글자의 텍스트 내용 업데이트
   727→    for (let i = 0; i < this.feverTimeUITexts.length; i++) {
   728→      if (i < newText.length) {
   729→        this.feverTimeUITexts[i].setText(newText[i]);
   730→      }
   731→    }
   732→
   733→    // 텍스트 길이가 변경된 경우 (초 카운트 변경) 위치 재조정
   734→    if (this.feverTimeUITexts.length > 0) {
   735→      const tempText = this.add.text(0, 0, newText, {
   736→        fontSize: FEVER_TIME_CONFIG.ui.fontSize,
   737→        fontStyle: 'bold'
   738→      });
   739→      const totalWidth = tempText.width;
   740→      tempText.destroy();
   741→
   742→      const startX = FEVER_TIME_CONFIG.ui.position.x - totalWidth / 2;
   743→      let currentX = startX;
   744→
   745→      for (let i = 0; i < this.feverTimeUITexts.length && i < newText.length; i++) {
   746→        this.feverTimeUITexts[i].setX(currentX);
   747→        currentX += this.feverTimeUITexts[i].width;
   748→      }
   749→    }
   750→
   751→    // 시간이 다 떨어지면 피버 타임 종료
   752→    if (this.feverTimeRemaining <= 0) {
   753→      this.endFeverTime();
   754→    }
   755→  }
