   757→  /**
   758→   * 피버 타임 색상 애니메이션 업데이트
   759→   */
   760→  private updateFeverTimeColors() {
   761→    // 무지개 색상 배열 (빨강, 주황, 노랑, 초록, 파랑, 남색, 보라)
   762→    const rainbowColors = [
   763→      '#ff0000', // 빨강
   764→      '#ff7f00', // 주황
   765→      '#ffff00', // 노랑
   766→      '#00ff00', // 초록
   767→      '#0000ff', // 파랑
   768→      '#4b0082', // 남색
   769→      '#9400d3'  // 보라
   770→    ];
   771→
   772→    // 색상 오프셋을 감소시켜 반대 방향으로 이동 (오른쪽에서 왼쪽으로)
   773→    this.feverTimeColorOffset = (this.feverTimeColorOffset - 1 + rainbowColors.length) % rainbowColors.length;
   774→
   775→    // 각 글자의 색상 업데이트
   776→    for (let i = 0; i < this.feverTimeUITexts.length; i++) {
