   852→          const baseFallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement) - POOP_CONFIG.diamond.speedReduction;
   853→          const fallSpeed = baseFallSpeed * FEVER_TIME_CONFIG.speedMultiplier;
