    if (!this.textures.exists('light_saber')) this.load.image('light_saber', 'assets/items/light_saber.webp');
    if (!this.textures.exists('rainbow_star')) this.load.image('rainbow_star', 'assets/items/rainbow_star.webp');

    // BGM
